-- PHY 108 (General Physics Practical II: vibrations, waves, optics and electricity)
-- =============================================================================
-- 55 original questions on the practical-physics topics in the department manual
-- (volume 2): errors and standard error, graph analysis, spring and pendulum
-- oscillations, lenses and mirrors, the prism, resonance and stationary waves, and
-- electrical measurements. Every answer was re-solved and checked numerically.
-- Corrections to the booklet's circled answers: a concave-mirror object at 20 cm with an
-- image at 40 cm gives f = 13.3 cm (no option of 10 cm is right), and the centroid of the
-- 1/v against 1/u graph is (0.046, 0.022) cm^-1, not (30, 50).
-- Subject: reuses an existing PHY 108 / PHY 192 subject if there is one; otherwise it is
-- created as 'phy-108-practical-physics-2'. ADDS ONLY; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('Two readings of the focal length of a lens are $11.3\ \text{cm}$ and $11.5\ \text{cm}$. The mean value and its standard error are:', '["$11.4 \\pm 0.1\\ \\text{cm}$","$11.4 \\pm 0.2\\ \\text{cm}$","$11.4 \\pm 0.01\\ \\text{cm}$","$11.5 \\pm 0.1\\ \\text{cm}$"]'::jsonb, 0, 'Mean $= 11.4\ \text{cm}$. Standard error $= \sqrt{\sum(x - \bar{x})^{2}/[n(n-1)]} = \sqrt{(0.01 + 0.01)/2} = 0.1\ \text{cm}$.', 'Errors and Measurement'),
  ('Five readings of a prism angle are all exactly $58^{\circ}$. The standard error in the mean is:', '["$1^{\\circ}$","zero","$58^{\\circ}$","$0.5^{\\circ}$"]'::jsonb, 1, 'Every deviation from the mean is zero, so $\sum(x - \bar{x})^{2} = 0$ and the standard error is zero (the instrument resolution still limits the true uncertainty).', 'Errors and Measurement'),
  ('A measured value is $9.6$ and the accepted value is $9.8$. The percentage error, using the accepted value as the standard, is about:', '["$0.2\\%$","$20\\%$","$2.0\\%$","$4.0\\%$"]'::jsonb, 2, '$|9.6 - 9.8|/9.8\times100 = 2.04\%$.', 'Errors and Measurement'),
  ('Which of the following is a systematic error?', '["reading a stop-watch slightly early and slightly late at random","fluctuations in room temperature","random errors in timing a swing","a metre rule whose zero end is worn away"]'::jsonb, 3, 'A worn zero end shifts every reading by the same amount in the same direction. Random errors scatter readings both ways.', 'Errors and Measurement'),
  ('Parallax error in reading a scale is avoided by:', '["placing the eye directly above the mark being read","taking the reading at an angle","using a thicker pointer","reading only when the scale is wet"]'::jsonb, 0, 'Parallax arises from viewing the pointer and scale from an angle. The eye should be perpendicular to the scale.', 'Errors and Measurement'),
  ('A student measures an angle whose true value is $80^{\circ}$ and records $100^{\circ}$. The most likely reason is that the student:', '["used the wrong type of lens","read the wrong scale of the protractor","recorded the angle in radians","measured the angle with a vernier caliper"]'::jsonb, 1, 'A reading of $100^{\circ}$ is the supplement of $80^{\circ}$ ($180^{\circ} - 80^{\circ}$), which shows that the other (inner or outer) scale was read.', 'Errors and Measurement'),
  ('The least count of a vernier caliper with $10$ divisions on the vernier equal to $9$ divisions of the main scale ($1\ \text{mm}$ each) is:', '["$1\\ \\text{mm}$","$0.9\\ \\text{mm}$","$0.1\\ \\text{mm}$","$0.01\\ \\text{mm}$"]'::jsonb, 2, 'Least count $= 1\ \text{MSD} - 1\ \text{VSD} = 1 - 0.9 = 0.1\ \text{mm}$.', 'Errors and Measurement'),
  ('The fractional error in $T$ is $1\%$ for a pendulum. The fractional error in $g = 4\pi^{2}L/T^{2}$ due to $T$ alone is:', '["$1\\%$","$0.5\\%$","$4\\%$","$2\\%$"]'::jsonb, 3, 'Since $g\propto T^{-2}$, the fractional error doubles: $2\times1\% = 2\%$.', 'Errors and Measurement'),
  ('For a straight-line graph $y = mx + c$, the best-fit line is the one that:', '["passes through the centroid of the points and has the points evenly scattered on both sides","passes through the first and last points only","always passes through the origin","joins the highest point to the lowest point"]'::jsonb, 0, 'The best line is drawn through the centroid (mean $x$, mean $y$), with points balanced on either side.', 'Graphs and Data Analysis'),
  ('The error in the slope of a graph is estimated from:', '["the number of points plotted","the difference between the best-fit slope and the slope of the worst acceptable line","the intercept on the $y$-axis","the units on the axes"]'::jsonb, 1, '$\Delta S = |S_{\text{best}} - S_{\text{worst}}|$.', 'Graphs and Data Analysis'),
  ('A graph has best slope $0.095\ \text{s}^{-1}$ and worst acceptable slope $0.15\ \text{s}^{-1}$. The slope with its error is:', '["$(0.095 \\pm 0.15)\\ \\text{s}^{-1}$","$(0.15 \\pm 0.095)\\ \\text{s}^{-1}$","$(0.10 \\pm 0.06)\\ \\text{s}^{-1}$","$(0.095 \\pm 0.0)\\ \\text{s}^{-1}$"]'::jsonb, 2, 'Error $= |0.15 - 0.095| = 0.055 \approx 0.06\ \text{s}^{-1}$, so the slope is $0.10 \pm 0.06\ \text{s}^{-1}$ (to the precision of the error).', 'Graphs and Data Analysis'),
  ('Object distances $u = 10, 20, 30, 40, 50\ \text{cm}$ gave image distances $v = 30, 40, 50, 60, 70\ \text{cm}$. A graph of $1/v$ against $1/u$ is plotted. The centroid is approximately:', '["$(30,\\ 50)\\ \\text{cm}$","$(0.022,\\ 0.046)\\ \\text{cm}^{-1}$","$(0.5,\\ 0.2)\\ \\text{cm}^{-1}$","$(0.046,\\ 0.022)\\ \\text{cm}^{-1}$"]'::jsonb, 3, 'Mean $1/u = (0.100 + 0.050 + 0.033 + 0.025 + 0.020)/5 = 0.046$. Mean $1/v = (0.033 + 0.025 + 0.020 + 0.017 + 0.014)/5 = 0.022$.', 'Graphs and Data Analysis'),
  ('In an experiment to find the focal length of a convex lens, a graph of $1/v$ against $1/u$ has intercept $0.05 \pm 0.01\ \text{cm}^{-1}$ on the $1/v$ axis. The focal length is:', '["$20 \\pm 4\\ \\text{cm}$","$0.05 \\pm 0.01\\ \\text{cm}$","$10 \\pm 0.5\\ \\text{cm}$","$0.5 \\pm 0.1\\ \\text{cm}$"]'::jsonb, 0, 'From $1/v + 1/u = 1/f$ the intercept is $1/f$. So $f = 1/0.05 = 20\ \text{cm}$, with $\Delta f = f(\Delta I/I) = 20(0.01/0.05) = 4\ \text{cm}$.', 'Graphs and Data Analysis'),
  ('In a graph of $uv$ against $(u + v)$ for a lens, the slope gives:', '["the magnification","the focal length","the inverse of the focal length","the object distance"]'::jsonb, 1, 'From $1/u + 1/v = 1/f$ we get $uv = f(u + v)$, a straight line through the origin of slope $f$.', 'Graphs and Data Analysis'),
  ('The graph of $uv$ against $(u + v)$ rises from $1700\ \text{cm}^{2}$ at $u + v = 90.5\ \text{cm}$ to $2060\ \text{cm}^{2}$ at $110\ \text{cm}$. The focal length is about:', '["$35\\ \\text{cm}$","$1.85\\ \\text{cm}$","$18.5\\ \\text{cm}$","$37\\ \\text{cm}$"]'::jsonb, 2, 'Slope $= \Delta(uv)/\Delta(u + v) = (2060 - 1700)/(110 - 90.5) = 360/19.5 = 18.5\ \text{cm}$, and the slope equals $f$.', 'Graphs and Data Analysis'),
  ('A plot of $\log A$ (where $A$ is the amplitude) against time $t$ for a damped spring is a straight line with intercept $1.6$ on the $\log A$ axis. The initial amplitude is about:', '["$1.6\\ \\text{cm}$","$16\\ \\text{cm}$","$4.0\\ \\text{cm}$","$40\\ \\text{cm}$"]'::jsonb, 3, '$\log A_{0} = 1.6$, so $A_{0} = 10^{1.6} = 39.8 \approx 40\ \text{cm}$.', 'Graphs and Data Analysis'),
  ('For exponential damping $A = A_{0}e^{-bt}$, the graph that is a straight line is:', '["$\\log A$ against $t$","$A$ against $t$","$A$ against $1/t$","$\\log A$ against $\\log t$"]'::jsonb, 0, '$\ln A = \ln A_{0} - bt$ is linear in $t$ with slope $-b$.', 'Graphs and Data Analysis'),
  ('A simple pendulum of length $1.00\ \text{m}$ has a period of $2.00\ \text{s}$. The value of $g$ is:', '["$9.00\\ \\text{m/s}^{2}$","$9.87\\ \\text{m/s}^{2}$","$19.7\\ \\text{m/s}^{2}$","$4.93\\ \\text{m/s}^{2}$"]'::jsonb, 1, '$g = 4\pi^{2}L/T^{2} = 4\pi^{2}(1.00)/4.00 = 9.87\ \text{m/s}^{2}$.', 'Vibrations and Oscillations'),
  ('A pendulum makes $60$ oscillations in $2$ minutes. Its frequency and period are:', '["$2.0\\ \\text{Hz};\\ 0.5\\ \\text{s}$","$0.5\\ \\text{Hz};\\ 0.5\\ \\text{s}$","$0.5\\ \\text{Hz};\\ 2.0\\ \\text{s}$","$30\\ \\text{Hz};\\ 0.033\\ \\text{s}$"]'::jsonb, 2, '$T = 120/60 = 2.0\ \text{s}$ and $f = 1/T = 0.5\ \text{Hz}$.', 'Vibrations and Oscillations'),
  ('In timing oscillations, the period is best found by:', '["timing a single oscillation","timing half an oscillation","measuring the amplitude only","timing many oscillations and dividing by their number"]'::jsonb, 3, 'Timing $n$ oscillations reduces the relative error of reaction time by a factor $n$.', 'Vibrations and Oscillations'),
  ('A mass of $200\ \text{g}$ hangs from a spring of constant $20\ \text{N/m}$. The period of vertical oscillation is:', '["$0.63\\ \\text{s}$","$0.10\\ \\text{s}$","$1.59\\ \\text{s}$","$6.3\\ \\text{s}$"]'::jsonb, 0, '$T = 2\pi\sqrt{m/k} = 2\pi\sqrt{0.2/20} = 0.63\ \text{s}$.', 'Vibrations and Oscillations'),
  ('A graph of $T^{2}$ against the mass $m$ on a spring is a straight line with slope $4\pi^{2}/k$. If the slope is $0.20\ \text{s}^{2}/\text{kg}$, then $k$ is about:', '["$7.9\\ \\text{N/m}$","$197\\ \\text{N/m}$","$0.80\\ \\text{N/m}$","$19.7\\ \\text{N/m}$"]'::jsonb, 1, '$k = 4\pi^{2}/\text{slope} = 39.48/0.20 = 197\ \text{N/m}$.', 'Vibrations and Oscillations'),
  ('Two springs with constants $0.4\ \text{N/m}$ and $0.2\ \text{N/m}$ carry equal masses. The ratio of their frequencies is:', '["$2 : 1$","$1 : 1$","$\\sqrt{2} : 1$","$4 : 1$"]'::jsonb, 2, '$f = \dfrac{1}{2\pi}\sqrt{k/m}$, so $f_{1}/f_{2} = \sqrt{0.4/0.2} = \sqrt{2} = 1.41$.', 'Vibrations and Oscillations'),
  ('What length of simple pendulum has a period of $1.5\ \text{s}$? (Take $g = 9.8\ \text{m/s}^{2}$.)', '["$0.37\\ \\text{m}$","$2.2\\ \\text{m}$","$1.5\\ \\text{m}$","$0.56\\ \\text{m}$"]'::jsonb, 3, '$L = gT^{2}/(4\pi^{2}) = 9.8(2.25)/39.48 = 0.56\ \text{m}$.', 'Vibrations and Oscillations'),
  ('For a simple pendulum, a graph of $T^{2}$ against $L$ is a straight line through the origin whose slope is:', '["$4\\pi^{2}/g$","$g/4\\pi^{2}$","$2\\pi\\sqrt{g}$","$g$"]'::jsonb, 0, '$T^{2} = (4\pi^{2}/g)L$, so the slope is $4\pi^{2}/g$.', 'Vibrations and Oscillations'),
  ('An object $20\ \text{cm}$ from a concave mirror gives a real image $40\ \text{cm}$ from it. The focal length is:', '["$10\\ \\text{cm}$","$13.3\\ \\text{cm}$","$20\\ \\text{cm}$","$60\\ \\text{cm}$"]'::jsonb, 1, '$1/f = 1/u + 1/v = 1/20 + 1/40 = 3/40$, so $f = 40/3 = 13.3\ \text{cm}$.', 'Lenses and Mirrors'),
  ('To estimate the approximate focal length of a convex lens, the distant object and the screen are placed:', '["on the same side of the lens","at right angles to the lens","on opposite sides of the lens","vertically above the lens"]'::jsonb, 2, 'Rays from a distant object are almost parallel and converge at the principal focus on the other side of the lens.', 'Lenses and Mirrors'),
  ('Where must an object be placed in front of a concave mirror so that the image forms at the same position as the object?', '["at the focus, giving a virtual image","between the focus and the mirror, giving an upright image","at infinity, giving a magnified image","at the centre of curvature, giving a real, inverted image of magnification 1"]'::jsonb, 3, 'For $u = v = R = 2f$ the image coincides with the object, is real and inverted, with $m = 1$.', 'Lenses and Mirrors'),
  ('A concave mirror has focal length $18.4\ \text{cm}$ from a graph. Its radius of curvature is:', '["$36.8\\ \\text{cm}$","$9.2\\ \\text{cm}$","$18.4\\ \\text{cm}$","$73.6\\ \\text{cm}$"]'::jsonb, 0, '$R = 2f = 2(18.4) = 36.8\ \text{cm}$.', 'Lenses and Mirrors'),
  ('A symmetric convex lens with radii of curvature $25\ \text{cm}$ has focal length $20\ \text{cm}$. Its refractive index is:', '["$1.25$","$1.63$","$2.25$","$1.50$"]'::jsonb, 1, '$1/f = (n - 1)(1/R_{1} + 1/R_{2}) = 2(n - 1)/R$, so $n = 1 + R/(2f) = 1 + 25/40 = 1.625$.', 'Lenses and Mirrors'),
  ('In the plane mirror experiment, the angle of reflection is found to be:', '["equal to $90^{\\circ}$ minus the angle of incidence","twice the angle of incidence","equal to the angle of incidence, both measured from the normal","always $0^{\\circ}$"]'::jsonb, 2, 'The law of reflection: $i = r$, with both angles measured from the normal.', 'Lenses and Mirrors'),
  ('The image formed by a plane mirror is:', '["real and inverted","virtual and magnified","real and the same size","virtual, upright, and as far behind the mirror as the object is in front"]'::jsonb, 3, 'A plane mirror gives a virtual, laterally inverted image of the same size at distance $v = u$ behind the mirror.', 'Lenses and Mirrors'),
  ('A convex lens forms an image $60\ \text{cm}$ from the lens of an object placed $20\ \text{cm}$ from it. The magnification is:', '["$3$ (real, inverted)","$1/3$ (virtual, upright)","$0.33$ (real, inverted)","$3$ (virtual, upright)"]'::jsonb, 0, '$m = v/u = 60/20 = 3$. A real image on a screen is inverted.', 'Lenses and Mirrors'),
  ('A convex lens of focal length $15\ \text{cm}$ has an object $30\ \text{cm}$ away. The image distance is:', '["$15\\ \\text{cm}$","$30\\ \\text{cm}$","$10\\ \\text{cm}$","$45\\ \\text{cm}$"]'::jsonb, 1, '$1/v = 1/f - 1/u = 1/15 - 1/30 = 1/30$, so $v = 30\ \text{cm}$ (object at $2f$ gives image at $2f$).', 'Lenses and Mirrors'),
  ('A prism of angle $58^{\circ}$ gives a minimum deviation of $34^{\circ}$. The refractive index of the glass is:', '["$1.17$","$1.80$","$1.48$","$0.67$"]'::jsonb, 2, '$n = \dfrac{\sin[(A + D_{\min})/2]}{\sin(A/2)} = \dfrac{\sin46^{\circ}}{\sin29^{\circ}} = \dfrac{0.7193}{0.4848} = 1.48$.', 'Prism and Refraction'),
  ('At minimum deviation in a prism, the angle of emergence $e$ is related to the angle of incidence $i$ by:', '["$e = 2i$","$e = i/2$","$e = 90^{\\circ} - i$","$e = i$"]'::jsonb, 3, 'At minimum deviation the ray passes symmetrically through the prism, so $i = e$.', 'Prism and Refraction'),
  ('A ray enters a prism of angle $60^{\circ}$ at an angle of incidence of $50^{\circ}$ and leaves at an angle of emergence of $70^{\circ}$. The deviation is:', '["$60^{\\circ}$","$120^{\\circ}$","$20^{\\circ}$","$30^{\\circ}$"]'::jsonb, 0, '$D = i + e - A = 50 + 70 - 60 = 60^{\circ}$.', 'Prism and Refraction'),
  ('In the $d$ against $i$ graph for a prism, the lowest point of the curve gives:', '["the angle of the prism","the minimum deviation and its angle of incidence","the refractive index directly","the critical angle"]'::jsonb, 1, 'The curve has a minimum at $D_{\min}$, where $i = e$.', 'Prism and Refraction'),
  ('For which colour is the refractive index of glass greatest?', '["red","yellow","violet","green"]'::jsonb, 2, 'Violet light has the shortest visible wavelength and is bent most (normal dispersion), so $n_{\text{violet}} > n_{\text{red}}$.', 'Prism and Refraction'),
  ('A ray goes from air into glass with angle of incidence $45^{\circ}$ and angle of refraction $30^{\circ}$. The refractive index of the glass is:', '["$0.71$","$1.50$","$1.73$","$1.41$"]'::jsonb, 3, '$n = \sin i/\sin r = 0.7071/0.5 = 1.41$.', 'Prism and Refraction'),
  ('The critical angle for glass of refractive index $1.50$ in air is about:', '["$41.8^{\\circ}$","$48.2^{\\circ}$","$33.7^{\\circ}$","$60.0^{\\circ}$"]'::jsonb, 0, '$\sin c = 1/n = 0.667$, so $c = 41.8^{\circ}$.', 'Prism and Refraction'),
  ('In a resonance tube experiment, the first and second resonances for a tuning fork of frequency $512\ \text{Hz}$ occur at $16.0\ \text{cm}$ and $49.0\ \text{cm}$. The speed of sound is:', '["$169\\ \\text{m/s}$","$338\\ \\text{m/s}$","$676\\ \\text{m/s}$","$84\\ \\text{m/s}$"]'::jsonb, 1, '$\lambda = 2(l_{2} - l_{1}) = 2(0.33) = 0.66\ \text{m}$. $v = f\lambda = 512\times0.66 = 338\ \text{m/s}$.', 'Waves and Sound'),
  ('A wave has wavelength $20\ \text{cm}$ and speed $200\ \text{cm/s}$. Its frequency is:', '["$100\\ \\text{Hz}$","$0.1\\ \\text{Hz}$","$10\\ \\text{Hz}$","$4000\\ \\text{Hz}$"]'::jsonb, 2, '$f = v/\lambda = 200/20 = 10\ \text{Hz}$.', 'Waves and Sound'),
  ('Stationary waves are formed by:', '["two waves travelling in the same direction","waves of different frequency in the same direction","a single wave reflected at an angle","two waves of the same frequency and amplitude travelling in opposite directions"]'::jsonb, 3, 'Superposition of a wave and its reflection gives nodes and antinodes that do not travel.', 'Waves and Sound'),
  ('A stretched string of length $0.50\ \text{m}$ has tension $100\ \text{N}$ and mass per unit length $1.0\ \text{g/m}$. Its fundamental frequency is:', '["$316\\ \\text{Hz}$","$158\\ \\text{Hz}$","$632\\ \\text{Hz}$","$100\\ \\text{Hz}$"]'::jsonb, 0, '$v = \sqrt{T/\mu} = \sqrt{100/0.001} = 316\ \text{m/s}$. $f_{1} = v/(2L) = 316/1.0 = 316\ \text{Hz}$.', 'Waves and Sound'),
  ('In an Ohm''s law experiment, a graph of $V$ against $I$ is a straight line through the origin. The slope gives:', '["the power dissipated","the resistance of the conductor","the e.m.f. of the cell","the charge on the electron"]'::jsonb, 1, '$V = IR$, so the slope $\Delta V/\Delta I = R$.', 'Electricity Practicals'),
  ('In a metre-bridge experiment, a known resistance of $20\ \Omega$ is in the left gap and the balance point is $55\ \text{cm}$ from the left end. The unknown resistance in the right gap is:', '["$24.4\\ \\Omega$","$36.7\\ \\Omega$","$16.4\\ \\Omega$","$11.0\\ \\Omega$"]'::jsonb, 2, 'At balance $R_{x}/20 = (100 - 55)/55$, so $R_{x} = 20\times45/55 = 16.4\ \Omega$.', 'Electricity Practicals'),
  ('When a voltmeter is connected in an experiment, it must be connected:', '["in series with the component","in series with the cell only","in parallel with the ammeter only","in parallel with the component"]'::jsonb, 3, 'A voltmeter has a very high resistance and measures the potential difference across a component, so it is placed in parallel.', 'Electricity Practicals'),
  ('An ammeter has to be connected:', '["in series with the component","in parallel with the component","across the cell terminals","in parallel with a voltmeter only"]'::jsonb, 0, 'An ammeter has a very small resistance and measures the current, so it is placed in series.', 'Electricity Practicals'),
  ('A cell has open-circuit voltage $2.0\ \text{V}$. When it supplies $0.50\ \text{A}$, its terminal voltage is $1.6\ \text{V}$. The internal resistance is:', '["$3.2\\ \\Omega$","$0.80\\ \\Omega$","$0.40\\ \\Omega$","$4.0\\ \\Omega$"]'::jsonb, 1, '$r = (E - V)/I = (2.0 - 1.6)/0.5 = 0.80\ \Omega$.', 'Electricity Practicals'),
  ('In a graph of terminal voltage $V$ against current $I$ for a cell, the intercept on the $V$ axis and the magnitude of the slope give:', '["the internal resistance and the e.m.f.","the power and the current","the e.m.f. and the internal resistance","the resistance and the charge"]'::jsonb, 2, '$V = E - Ir$: intercept $E$, slope $-r$.', 'Electricity Practicals'),
  ('A copper wire $2.0\ \text{m}$ long and $0.50\ \text{mm}$ in diameter has resistivity $1.7\times10^{-8}\ \Omega\,\text{m}$. Its resistance is about:', '["$0.69\\ \\Omega$","$0.043\\ \\Omega$","$1.7\\ \\Omega$","$0.17\\ \\Omega$"]'::jsonb, 3, '$R = \rho L/A$, with $A = \pi(0.25\times10^{-3})^{2} = 1.96\times10^{-7}\ \text{m}^{2}$. $R = 1.7\times10^{-8}\times2/1.96\times10^{-7} = 0.17\ \Omega$.', 'Electricity Practicals'),
  ('Two resistors of $10\ \Omega$ and $15\ \Omega$ are in parallel. The combined resistance is:', '["$6.0\\ \\Omega$","$25\\ \\Omega$","$12.5\\ \\Omega$","$5.0\\ \\Omega$"]'::jsonb, 0, '$R = (10\times15)/(10 + 15) = 6.0\ \Omega$.', 'Electricity Practicals'),
  ('When a diode is forward biased, in the current-voltage experiment:', '["no current flows at any voltage","current rises sharply once the voltage exceeds the threshold value","the current is proportional to voltage at all voltages","the current is constant"]'::jsonb, 1, 'A diode is non-ohmic. Little current flows until the threshold (about $0.6\ \text{V}$ for silicon), then the current rises very rapidly.', 'Electricity Practicals'),
  ('A graph of $V$ against $I$ for a filament lamp curves upward because:', '["the resistance decreases as it heats up","the e.m.f. of the cell rises","the resistance of the filament increases as its temperature rises","the current flows more slowly"]'::jsonb, 2, 'A hotter metal filament has greater resistance, so the $V$-$I$ line is not straight.', 'Electricity Practicals')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where (subject_name ilike 'PHY 108%' or subject_name ilike 'PHY 192%' or subject_id = 'phy-108-practical-physics-2')
     and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'phy-108-practical-physics-2'),
       coalesce(t.subject_name, 'PHY 108: General Physics Practical II'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies'),
       coalesce(t.department, 'Physics and Astronomy'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 2)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'phy-108-practical-physics-2') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'PHY 108%' or subject_id = 'phy-108-practical-physics-2'
 group by 1, 2;
